// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {StaxLPStaking} from "../src/StaxLPStaking.sol";

contract InvMutTest is Test {
    StaxLPStaking c;
    address owner;

    function setUp() public {
        c = new StaxLPStaking(address(new __InvMutHandleStub()), address(new __InvMutHandleStub()));
        owner = c.owner();
    }

    function testFuzz_property(address newOwner) public {
        // Admissible domain: any caller, but the new owner must be non-zero
        // (the reference contract itself requires this).
        vm.assume(newOwner != address(0));

        vm.prank(owner);
        c.transferOwnership(newOwner);

        // Universal rule: after transferOwnership(newOwner) by the owner with
        // newOwner != 0, the stored owner is exactly newOwner.
        assertTrue(c.owner() == newOwner);
    }
}

